"Venezuela": "ベネズエラ",
"Israel": "イスラエル",
"consulados y embajadas": "領事館と大使館",
"Viajes, comida, pagos": "配車・フード・支払い",
"Tocá el botón para bajar la app. Si ya la tenés, la tienda te muestra «Abrir».": "ボタンを押すとアプリを入手できます。インストール済みならストアに「開く」と表示されます。",
"Abrir o descargar": "開く/ダウンロード",
"Para comprar y pagar": "買い物と支払い",
"Para comunicarte": "連絡用",
"Viajes en auto y moto. Ves el precio antes de pedir.": "車とバイクの配車。予約前に料金がわかります。",
"Viajes en auto, también con precio de antemano.": "車の配車。こちらも料金が事前にわかります。",
"Viajes en auto, suele ser la más barata.": "車の配車。たいてい一番安いです。",
"Mapas y recorridos en subte, colectivo y a pie.": "地図と地下鉄・バス・徒歩のルート。",
"Qué colectivo o subte tomar, con horarios en vivo.": "どのバスや地下鉄に乗るか、リアルタイムの時刻つき。",
"Las bicis públicas de la Ciudad.": "市の公共レンタサイクル。",
"Comida, súper y farmacia a domicilio. La más usada.": "料理・スーパー・薬局の宅配。一番使われています。",
"Comida y compras a domicilio.": "料理と買い物の宅配。",
"Muchos comercios cobran con su QR.": "多くの店がこのQRコードで支払いを受けます。",
"Para comprar casi cualquier cosa por internet.": "ほとんど何でもネットで買えます。",
"Acá todo se arregla por WhatsApp: reservas, consultas y turnos.": "ここでは予約や問い合わせ、受付まで何でもWhatsAppです。",
"Recorridos en U-Bahn, S-Bahn, tranvía y colectivo. En alemán e inglés.": "U-Bahn・S-Bahn・トラム・バスのルート。ドイツ語と英語。",
"Para comprar el boleto en el celular.": "スマホで切符を買えます。",
"Mapas y recorridos en transporte y a pie.": "地図と交通機関・徒歩のルート。",
"Viajes en auto. Ves el precio antes de pedir.": "車の配車。予約前に料金がわかります。",
"Para pedir taxis.": "タクシーを呼べます。",
"La más usada para escribir y llamar.": "メッセージや通話で一番使われています。",
"Creá tu cuenta o entrá con tu mail": "メールでアカウント作成・ログイン",
"Solo tu mail, sin contraseña: te mandamos un enlace y con tocarlo ya estás adentro. Lo único que guardamos es tu mail y tu viaje.": "メールだけでパスワード不要。届いたリンクを押せばログインできます。保存するのはメールと旅行プランだけです。",
"Enviar enlace": "リンクを送信",
"Entraste como": "ログイン中:",
"Tu viaje se guarda en tu cuenta. En este dispositivo ya no te vamos a pedir el mail. Lo único que sabemos de vos es tu mail.": "旅行はアカウントに保存されます。この端末ではもうメールアドレスを聞きません。私たちが知っているのはあなたのメールアドレスだけです。",
