"No pudimos conectar con el servicio de cuentas. Probá más tarde.": "アカウントサービスに接続できませんでした。後でもう一度お試しください。",
"Todavía estamos conectando con el servicio de cuentas. Probá en unos segundos.": "アカウントサービスに接続中です。数秒後にお試しください。",
