"Tienda León, desde Ezeiza": "ティエンダ・レオン、エセイサから",
"Taxis y remises: contratalos en los mostradores oficiales de adentro del aeropuerto.": "タクシーとハイヤー：空港内の公式カウンターで予約を。",
"No aceptes ofertas de gente que se te acerque en el hall.": "ロビーで声をかけてくる人の誘いには乗らないこと。",
"Ezeiza queda lejos del centro: contá con un buen rato de viaje.": "エセイサは中心部から遠いので、移動に時間がかかります。",
