"Sin chip físico": "物理SIM不要",
"Tiendas cerca": "近くの店舗",
"Para comprar un chip te pueden pedir el pasaporte.": "SIMを買うときにパスポートを求められることがあります。",
"Si tu celular acepta eSIM, podés activarla antes de viajar.": "スマホがeSIM対応なら、出発前に有効化できます。",
"Muchos bares y cafés tienen Wi-Fi gratis: pedí la clave.": "多くのバーやカフェに無料Wi-Fiがあります。パスワードを聞きましょう。",
"Cajeros cerca": "近くのATM",
"Casas de cambio": "両替所",
"Oficiales, en el mapa": "公式の両替所を地図で",
