"Se combina con la Fragata Sarmiento.": "サルミエント号と組み合わせて。",
"Queda a pasos de la Reserva Ecológica.": "エコロジカル・リザーブからすぐ。",
"Se ve desde la Vuelta de Rocha. Andá de día.": "ブエルタ・デ・ロチャから見えます。昼間に。",
"Abre algunos días por semana; confirmá antes de ir.": "開館は週に数日。行く前に確認を。",
"Circula los fines de semana y feriados, y es gratis.": "週末と祝日に運行、無料です。",
