"Ideal para un almuerzo largo de invierno.": "冬のゆっくりランチに最適。",
"Clásico para antes o después del teatro.": "観劇の前後の定番。",
"Muy elegido para comer después del teatro.": "観劇後の食事に人気。",
"Se come de parado en la barra, como manda la tradición.": "伝統どおり、カウンターで立って食べます。",
"Pizza a la piedra, más fina que la de sus vecinas.": "石窯焼きのピザで、近所の店より薄め。",
"Perfecto para una tarde fría.": "寒い午後にぴったり。",
"A una cuadra de Plaza de Mayo.": "五月広場から1ブロック。",
"Bajá a ver las mesas aunque no juegues.": "プレーしなくても、地下のビリヤード台を見に行って。",
