"Buen descanso después del Museo Histórico Nacional.": "国立歴史博物館のあとのひと休みに。",
"Probá el sándwich de crudo y queso.": "生ハムとチーズのサンドイッチをぜひ。",
"Reservá los fines de semana.": "週末は予約を。",
"Bueno y barato para seguir caminando.": "安くておいしい、街歩きの燃料に。",
"El patio es un oasis en un día de feria.": "市の日には中庭がオアシスに。",
"Almuerzo ideal para la visita a La Boca. Solo de día.": "ラ・ボカ観光のランチに最適。昼間のみ。",
