"Andá de noche a jugar al ping-pong con una cerveza.": "夜に行って、ビール片手に卓球を。",
"Los fines de semana hay espera para el brunch.": "週末のブランチは待ち時間あり。",
"Picada y vermut para el atardecer.": "夕暮れにピカーダとベルモットを。",
"Pedí pastas caseras.": "自家製パスタを注文して。",
"Bien de vecinos: sin vueltas y barata.": "地元の人の店：飾り気がなく安い。",
"Los domingos al mediodía se llena de familias.": "日曜のお昼は家族連れでいっぱい。",
"Los domingos combinalo con la feria de libros del parque.": "日曜は公園の古本市と組み合わせて。",
"Suele haber fila. Algunas cosas se agotan temprano.": "たいてい行列。早く売り切れるものも。",
