"Antes del show suelen dar una clase.": "ショーの前にレッスンがあることが多いです。",
"A pasos de la Casa Museo Carlos Gardel.": "カルロス・ガルデル博物館からすぐ。",
"Mirá los códigos: se invita a bailar con la mirada.": "マナーに注意：ダンスの誘いは目線で。",
