"A pasos del subte y de la calle Florida.": "地下鉄とフロリダ通りからすぐ。",
"Pedí habitación con vista a la 9 de Julio.": "7月9日大通りが見える部屋を頼んで。",
"Bien ubicado para ir al teatro caminando.": "劇場まで歩いて行ける好立地。",
"Cerca de Puerto Madero y del Palacio Libertad.": "プエルト・マデロとリベルタ宮殿の近く。",
