"El bar de la terraza tiene vista de 360°.": "ルーフトップバーからは360°の眺め。",
"En pleno Palermo Soho, pero silencioso.": "パレルモ・ソーホーの真ん中なのに静か。",
"Tiene una pileta chica en la terraza.": "屋上に小さなプールがあります。",
"Bien ubicado entre los parques y Palermo Soho.": "公園とパレルモ・ソーホーの間の好立地。",
