"Una de las maratones más rápidas del mundo; hay cortes de tránsito ese domingo.": "世界有数の高速マラソン。当日の日曜は交通規制があります。",
"3 de octubre": "10月3日",
"Día de la Unidad Alemana": "ドイツ統一の日",
"Feriado nacional: comercios cerrados y festejos cerca de la Puerta de Brandeburgo.": "国の祝日：商店は休みで、ブランデンブルク門の近くで祝賀行事があります。",
