"Cruzalo hasta la Columna de la Victoria.": "戦勝記念塔まで横切って歩きましょう。",
"Día 3 · Merienda": "3日目 · おやつ",
"Día 3 · Noche": "3日目 · 夜",
"Si hay concierto, conseguí entrada con tiempo.": "コンサートがあれば早めにチケットを。",
"Todo bajo techo y cerca.": "すべて屋内で、近くにまとまっています。",
"Cierra los lunes: ese día cambialo por el DDR Museum.": "月曜休館：その日はDDR博物館に変更を。",
