"Libros y discos en cinco pisos.": "5フロアの本とレコード。",
"Un gran día sin pagar entradas.": "入場料なしで楽しむ充実の1日。",
"Gratis, con inscripción previa.": "無料、事前登録制。",
"La muestra permanente es gratis.": "常設展は無料です。",
"Desde el ventanal se ven los monos del zoológico.": "大きな窓から動物園のサルが見えます。",
"Trenes, barcos y aviones. Cierra los lunes.": "列車、船、飛行機。月曜休館。",
