"Adaptador de enchufe tipo F o L (230 V)": "F型またはL型の変換プラグ（230V）",
"Reservar el Coliseo, los Museos Vaticanos y la Galería Borghese": "コロッセオ、ヴァチカン美術館、ボルゲーゼ美術館を予約",
"Tomar el Leonardo Express o el taxi a precio fijo desde Fiumicino": "フィウミチーノからレオナルド・エクスプレスか定額タクシーで",
"Pagar el transporte con la tarjeta sin contacto, o comprar un pase": "交通機関はタッチ決済のカードで払うか、パスを購入",
"Llevar un pañuelo para entrar a las iglesias con los hombros tapados": "肩を覆って教会に入れるようスカーフを持参",
