"Revisá la programación: abre según la temporada.": "スケジュールを確認して。季節によって営業します。",
"Visita guiada que entra a los pasillos subterráneos donde esperaban los gladiadores y las fieras, y sale a la arena.": "剣闘士や猛獣が待機した地下通路に入り、アリーナに出るガイドツアー。",
