"Muy pocos cupos: se pide por correo a la Oficina de Excavaciones con meses de anticipación.": "定員がとても少なく、数か月前に発掘事務所へメールで申し込みます。",
"Restos de casas romanas bajo un palacio, contados con proyecciones de luz que las reconstruyen.": "宮殿の地下に残るローマの邸宅跡を、光のプロジェクションで再現して紹介します。",
"Visita con horario: reservá. Muy bueno para chicos.": "時間指定制なので要予約。子どもにもおすすめ。",
"tecnología": "テクノロジー",
