"Varias empresas lo ofrecen; reservá por internet.": "複数の会社が催行。ネットで予約を。",
"Clases para aprender a amasar pasta fresca y salsas romanas, con comida incluida.": "生パスタとローマのソースの作り方を学ぶ料理教室。食事付き。",
"Hay muchas; elegí una con buenas reseñas recientes.": "たくさんあるので、最近の評価が良いものを選んで。",
"Recorridos en Vespa con conductor por la ciudad, como en las películas.": "運転手付きのベスパで街を巡るツアー。映画のように。",
