"París en 1 día": "1日でパリ",
"Temprano, con horario reservado.": "早めに、時間指定の予約をして。",
"Está a dos cuadras.": "2ブロック先です。",
"Caminá por la orilla hasta el Louvre.": "川沿いを歩いてルーヴルへ。",
"Elegí dos o tres salas.": "2〜3つの展示室に絞って。",
"Desde la Concordia hasta el Arco.": "コンコルドから凱旋門まで。",
"Subí a la terraza.": "テラスに上りましょう。",
"Mirá el brillo de la hora en punto.": "正時のきらめきを見て。",
