"Día 3": "3日目",
"O una cena en Montmartre.": "またはモンマルトルで夕食を。",
"Los pasajes cubiertos son para la lluvia.": "雨の日はパッサージュへ。",
"Chocolate caliente.": "ホットチョコレート。",
"París gratis": "無料で楽しむパリ",
"La colección permanente es gratis.": "常設展は無料です。",
"Vista de la Torre Eiffel iluminada.": "ライトアップされたエッフェル塔の眺め。",
"Barquitos en la fuente.": "噴水でおもちゃの帆船。",
"Paseo en barco por el Sena.": "セーヌ川の遊覧船。",
