"El origen de París": "パリ発祥の地",
"La isla de la Cité, con Notre-Dame, la Sainte-Chapelle y la Conciergerie, y la tranquila isla Saint-Louis, unidas por puentes.": "ノートルダム、サント・シャペル、コンシェルジュリーのあるシテ島と、静かなサン・ルイ島。橋でつながっています。",
"Hay muy pocos hoteles, pero todo lo demás queda a un paso.": "ホテルはごくわずかですが、ほかは何でもすぐそば。",
"Barrio Chino y colina de pueblo": "中華街と村のような丘",
"El Barrio Chino entre torres modernas y, al lado, la Butte-aux-Cailles, con casas bajas, arte urbano y bares baratos.": "近代的な高層ビルの間の中華街と、隣のビュット・オ・カイユ。低い家並み、ストリートアート、安いバー。",
"Económico y bien conectado, lejos del circuito turístico.": "手頃で交通便利、観光ルートから離れています。",
"Residencial y elegante": "上品な住宅街",
"El oeste tranquilo de la ciudad, con el Museo Marmottan Monet, calles comerciales de barrio y el bosque de Boulogne cerca.": "マルモッタン・モネ美術館や街の商店街がある静かな西部。ブローニュの森も近くです。",
"Muy seguro y silencioso, pero lejos de la vida nocturna.": "とても安全で静かですが、夜遊びからは遠め。",
"Verde y enorme": "緑豊かで広大",
"El gran bosque del oeste de París, con lagos, la Fundación Louis Vuitton y el Jardín de Aclimatación.": "湖、ルイ・ヴィトン財団、アクリマタシオン公園があるパリ西部の大きな森。",
"No es zona para alojarse: es para pasar el día.": "宿泊向けではなく、1日過ごすための場所です。",
"Moderno y al aire libre": "モダンで開放的",
"El gran parque del noreste, con la Ciudad de las Ciencias, la Philharmonie y canales para caminar.": "科学産業博物館、フィルハーモニー、散歩できる運河がある北東部の大公園。",
"Mejor para visitar que para alojarse.": "滞在より観光向き。",
